package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.support.TransactionSynchronizationManager;import java.util.*;import java.math.*;import java.time.*;import com.ruoyi.medical.contracts.*;
/** Actual accounting branch and SQL mutations. Original authority, SQL rows and final independent reader are test boundaries. */
class FormalInvocationSettlementTest {
 FormalInvocationSchema schema;FormalInvocationSettlement service;JdbcTemplate db;FormalInvocationOutcomeAuthority.VerifiedOutcome outcome;FormalProviderCaptureEvidence.Verified capture;FormalInvocationObjectRegistration.Registered resultObject,captureObject;TenantScope scope;String tenant=id(1),actor=id(2),inv=id(3),priceId=id(4);String price,hash="a".repeat(64);BigInteger total=BigInteger.valueOf(5),calls=BigInteger.ONE;BigDecimal upper=BigDecimal.TEN;boolean terminal=true;
 @BeforeEach void setup()throws Exception{schema=new FormalInvocationSchema();TransactionSynchronizationManager.setActualTransactionActive(true);scope=TenantScope.open(new TenantScope.Identity(tenant,actor,BigInteger.ZERO,BigInteger.ONE,BigInteger.ONE));db=mock(JdbcTemplate.class);var jobs=mock(FormalVerificationJobs.class);var registrations=mock(FormalInvocationObjectRegistration.class);var reservations=mock(FormalInvocationReservations.class);service=spy(new FormalInvocationSettlement(mock(javax.sql.DataSource.class),schema,jobs,registrations,reservations));var field=FormalInvocationSettlement.class.getDeclaredField("db");field.setAccessible(true);field.set(service,db);
  price="{\"schema_version\":\"1.0.0\",\"kind\":\"TOKEN_ONLY_PER_MILLION\",\"provider\":\"deepseek\",\"model_id\":\"deepseek-chat\",\"model_version\":\"fixed\",\"currency\":\"USD\",\"uncached_input_per_million\":\"0\",\"cache_read_per_million\":\"0\",\"cache_write_per_million\":\"0\",\"output_per_million\":\"0\",\"rounding\":\"CEILING_8_DECIMAL_PLACES\"}";price=schema.canonical(schema.parse(price));var deps=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();deps.set("price",schema.parse(price));var job=new FormalVerificationJobs.Job(tenant,id(5),id(6),id(7),actor,"original-key-000000",id(8),id(9),id(10),id(11),id(12),id(13),id(14),id(15),id(16),"{}",hash,hash,schema.canonical(deps),hash,schema.manifestSha256(),LocalDateTime.of(2026,10,18,1,0),"INTERNAL");when(jobs.byRun(tenant,id(8))).thenReturn(job);
  outcome=mock(FormalInvocationOutcomeAuthority.VerifiedOutcome.class);when(outcome.tenantId()).thenReturn(tenant);when(outcome.invocationId()).thenReturn(inv);when(outcome.attemptId()).thenReturn(id(17));when(outcome.binding()).thenReturn(schema.parse("{\"run_id\":\""+id(8)+"\"}"));when(outcome.result()).thenReturn(schema.parse("{\"reason\":{\"kind\":\"stop\"},\"provider_request_id\":\"actual-response\"}"));capture=mock(FormalProviderCaptureEvidence.Verified.class);when(capture.artifact()).thenReturn(schema.parse("{}"));when(capture.receiptId()).thenReturn(id(18));when(capture.providerTerminal()).thenAnswer(i->terminal);when(capture.confirmedCalls()).thenAnswer(i->calls);when(capture.usage()).thenAnswer(i->new FormalInvocationPricing.ObservedUsage(null,null,null,null,total));
  resultObject=registered(id(19),outcome.result());captureObject=registered(id(20),capture.artifact());doReturn(Optional.empty(),Optional.of(mock(FormalInvocationSettlement.Recorded.class))).when(service).read(tenant,inv);
  when(db.query(anyString(),any(RowMapper.class),any(Object[].class))).thenAnswer(i->{String sql=i.getArgument(0);if(sql.startsWith("SELECT canonical_price"))return List.of(List.of(price,schema.hash(schema.parse(price)),id(21),id(22)));if(sql.startsWith("SELECT status,settlement_status"))return List.of(List.of("DISPATCHING","PENDING",priceId,"2"));if(sql.startsWith("SELECT reservation_id")){var c=Class.forName(FormalInvocationSettlement.class.getName()+"$Reservation").getDeclaredConstructors()[0];c.setAccessible(true);return List.of(c.newInstance(id(21),id(23),id(25),upper,BigInteger.TEN,"RESERVED",BigInteger.ONE),c.newInstance(id(22),id(24),id(26),upper,BigInteger.TEN,"RESERVED",BigInteger.ONE));}if(sql.startsWith("SELECT admitted_at"))return List.of(LocalDateTime.of(2026,10,18,1,1));if(sql.startsWith("SELECT revision,reserved"))return List.of(List.of(BigDecimal.ONE,upper,BigDecimal.TEN,BigDecimal.ONE));throw new AssertionError(sql);});when(db.query(eq("SELECT UTC_TIMESTAMP(6)"),any(RowMapper.class))).thenReturn(List.of(LocalDateTime.of(2026,10,18,1,2)));when(db.update(anyString(),any(Object[].class))).thenReturn(1);
 }
 FormalInvocationObjectRegistration.Registered registered(String artifact,com.fasterxml.jackson.databind.JsonNode payload){var p=mock(FormalInvocationObjectRegistration.Registered.class);when(p.invocationId()).thenReturn(inv);when(p.attemptId()).thenReturn(id(17));when(p.canonicalPayload()).thenReturn(payload);when(p.objectReceiptSha256()).thenReturn(hash);when(p.artifact()).thenReturn(new CommonProtocol.ArtifactRef(artifact,hash,"urn:fixture",new CommonProtocol.Coverage(hash,hash,true,null)));return p;}
 @AfterEach void close(){scope.close();TransactionSynchronizationManager.clear();}
 void run()throws Exception{service.record(outcome,capture,resultObject,captureObject);}
 @Test void knownZeroMoneyAndKnownUsageSettleBothRealReservations()throws Exception{run();verify(db,times(2)).update(startsWith("UPDATE budget_account SET reserved="),any(Object[].class));verify(db).update(startsWith("INSERT INTO invocation_receipt"),any(Object[].class));verify(outcome,times(2)).requireActive();}
 @Test void zeroMoneyWithUnknownTokensNeverReleasesReservations()throws Exception{total=null;calls=null;run();verify(db,never()).update(startsWith("UPDATE budget_account"),any(Object[].class));verify(db,never()).update(startsWith("UPDATE budget_reservation"),any(Object[].class));}
 @Test void KnownUsageWithoutProviderTerminalNeverSettles()throws Exception{terminal=false;run();verify(db,never()).update(startsWith("UPDATE budget_account"),any(Object[].class));}
 @Test void overUpperTokensPreservesAccountReservationAndMarksDispute()throws Exception{total=BigInteger.valueOf(11);run();verify(db,never()).update(startsWith("UPDATE budget_account"),any(Object[].class));verify(db,times(2)).update(startsWith("UPDATE budget_reservation"),any(Object[].class));}
 @Test void staleOriginalServiceCannotMutateAnyLedger()throws Exception{doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(outcome).requireActive();assertThrows(TenantAccessException.class,this::run);verify(db,never()).update(anyString(),any(Object[].class));}
 static String id(int n){return "00000000-0000-4000-8000-"+String.format("%012d",n);}
}
